INSERT INTO `v1_26a05860e4d3281177856ff5981d6586ea4843496757a5a6897420e3531ccf94` VALUES (6, "サマー衣装のツムギが、キャップでオンステージ！涼しげな衣装を\nまとい、熱いステージを繰り広げた彼女の勇姿を思い出すことがで\nきる。", 1, 11602, 0.75, "ツムギのサマーボトルキャップ", 0.625);
